<script setup lang="ts">
import {computed,nextTick,onUnmounted,ref,watch} from 'vue'; import {saveMetricResult,saveResult} from '../data/topics'; import MascotCharacter from '../components/MascotCharacter.vue';
type Bin='fix'|'report'|'ignore'|'disclose';
const stage=ref<'brief'|'catch'|'trace'|'handoff'|'damage'|'result'>('brief');
const catchScore=ref(0),draggedBug=ref<number|null>(null),placements=ref<Record<number,Bin>>({}),catchFeedback=ref('');
const bugPool:{name:string;icon:string;clue:string;bin:Bin;why:string}[]=[
{name:'Paint Moth',icon:'◆',clue:'The button color differs on one old browser. No action or data is affected.',bin:'ignore',why:'Record it as low priority; it does not justify interrupting the incident queue.'},
{name:'Receipt Beetle',icon:'⬢',clue:'Some transfers create two real charge records when the network retries.',bin:'fix',why:'This active defect creates direct financial harm. It needs containment and a code fix now.'},
{name:'Keywing',icon:'✦',clue:'Changing an account ID reveals another user’s transfer history.',bin:'report',why:'Treat this as a security incident: preserve evidence and escalate before wider communication.'},
{name:'Alarm Fly',icon:'●',clue:'The leak is contained; 430 affected users are confirmed and protective steps are ready.',bin:'disclose',why:'Affected users now need a timely, useful notice explaining impact and next steps.'},
{name:'Tooltip Gnat',icon:'◇',clue:'One help tooltip has a spelling mistake. The control underneath still works.',bin:'ignore',why:'Track it for routine cleanup, but keep the active-response queue focused on user harm.'},
{name:'Session Wasp',icon:'✶',clue:'A valid session remains active after a user changes their password.',bin:'report',why:'This security weakness needs evidence preserved and immediate escalation for investigation.'},
{name:'Balance Locust',icon:'⬟',clue:'Account balances are rounded incorrectly after a foreign-currency transfer.',bin:'fix',why:'Incorrect financial records directly affect users and require an urgent verified fix.'},
{name:'Notice Firefly',icon:'•',clue:'A confirmed outage prevented 900 users from accessing funds; service is restored.',bin:'disclose',why:'Affected users need a clear notice describing impact, restoration, and available support.'},
{name:'Shadow Ant',icon:'▲',clue:'A scanner reports an unused demo route that is disabled in production.',bin:'ignore',why:'The current evidence shows no reachable production risk. Document it and verify during routine review.'},
{name:'Token Hornet',icon:'✹',clue:'Password-reset tokens appear unredacted in a shared support log.',bin:'report',why:'Secure the log and escalate because credentials and user access may be exposed.'},
{name:'Fee Cricket',icon:'◈',clue:'A late-payment fee runs twice when two workers process the same queue item.',bin:'fix',why:'The repeatable processing defect causes financial harm and needs containment plus a durable fix.'},
{name:'Breach Cicada',icon:'⬣',clue:'Investigation confirms customer statements were exposed and the download link is now disabled.',bin:'disclose',why:'With containment and scope confirmed, customers need timely and actionable communication.'}];
const bugCount=6+Math.floor(Math.random()*4);
const receipt=bugPool.find(b=>b.name==='Receipt Beetle')!;
const shuffled=bugPool.filter(b=>b!==receipt).sort(()=>Math.random()-.5);
const bugs=[receipt,...shuffled.slice(0,bugCount-1)].sort(()=>Math.random()-.5);
const bins:{id:Bin;label:string;hint:string;icon:string}[]=[{id:'fix',label:'FIX',hint:'repair now',icon:'✚'},{id:'report',label:'REPORT',hint:'escalate evidence',icon:'!'},{id:'ignore',label:'IGNORE',hint:'no urgent action',icon:'⌁'},{id:'disclose',label:'DISCLOSE',hint:'notify people',icon:'✦'}];
function startDrag(index:number,event:DragEvent){draggedBug.value=index;event.dataTransfer?.setData('text/plain',String(index));if(event.dataTransfer)event.dataTransfer.effectAllowed='move'}
function placeBug(bin:Bin,index:number|null){if(index===null||Number.isNaN(index)||placements.value[index])return;const bug=bugs[index]!;placements.value={...placements.value,[index]:bin};if(bin===bug.bin)catchScore.value++;catchFeedback.value=`${bug.name} → ${bin.toUpperCase()} · ${bin===bug.bin?'Good triage.':'Expected '+bug.bin.toUpperCase()+'.'} ${bug.why}`;draggedBug.value=null}
function dropBug(bin:Bin,event:DragEvent){const raw=event.dataTransfer?.getData('text/plain');placeBug(bin,raw!==undefined&&raw!==''?Number(raw):draggedBug.value)}
function continueToTrace(){if(Object.keys(placements.value).length===bugs.length)stage.value='trace'}
const evidence=[{id:'retry',title:'Gateway log',body:'The same transfer appears twice after a timeout. Both calls share one request ID.'},{id:'code',title:'Payment handler',body:'A charge is created before checking whether the request ID was already processed.'},{id:'support',title:'Support queue',body:'Users report duplicate charges, but no unauthorized account access.'}];
const opened=ref<string[]>([]),traceChoice=ref(''),traceScore=ref(0);function openEvidence(id:string){if(!opened.value.includes(id))opened.value.push(id)}function diagnose(choice:string){if(traceChoice.value)return;traceChoice.value=choice;traceScore.value=choice==='idempotency'?100:choice==='hide'?20:45}
const damage=ref(1200),users=ref(12),elapsed=ref(0),activeAction=ref(''),remaining=ref(0),completed=ref<string[]>([]),incidentLog=ref<string[]>([]),actionOrder=ref<string[]>([]),actionCompletedAt=ref<Record<string,number>>({});
const actions=[{id:'stop',label:'STOP TRANSACTIONS',seconds:3,detail:'Freeze new transfers'},{id:'rollback',label:'ROLLBACK',seconds:8,detail:'Return to stable build'},{id:'notify',label:'NOTIFY USERS',seconds:4,detail:'Show incident notice'},{id:'refund',label:'REFUND',seconds:6,detail:'Reverse duplicate charges'},{id:'record',label:'RECORD INCIDENT',seconds:3,detail:'Preserve logs and timeline'}];
let damageTimer:number|undefined,actionTimer:number|undefined;
function startDamage(){stage.value='damage';damage.value=1200+(traceScore.value<80?900:0);damageTimer=window.setInterval(()=>{elapsed.value++;if(!completed.value.includes('stop')){damage.value+=300;users.value+=3}},1000)}
function runAction(id:string){if(activeAction.value||completed.value.includes(id))return;const a=actions.find(x=>x.id===id)!;activeAction.value=id;actionOrder.value.push(id);remaining.value=a.seconds;incidentLog.value.unshift(`${a.label} started at ${elapsed.value}s`);actionTimer=window.setInterval(()=>{remaining.value--;if(remaining.value<=0){clearInterval(actionTimer);activeAction.value='';completed.value.push(id);actionCompletedAt.value={...actionCompletedAt.value,[id]:elapsed.value};incidentLog.value.unshift(`${a.label} complete`);if(completed.value.length===actions.length)finishIncident()}},1000)}
function finishIncident(){clearInterval(damageTimer);const clamp=(value:number)=>Math.max(20,Math.min(100,Math.round(value)));const order=(id:string)=>Math.max(0,actionOrder.value.indexOf(id));const triage=clamp(catchScore.value/bugs.length*100);const investigation=clamp(traceScore.value);const containment=clamp(100-Math.max(0,(actionCompletedAt.value.stop||elapsed.value)-4)*5-order('stop')*15);const communication=clamp(100-Math.max(0,(actionCompletedAt.value.notify||elapsed.value)-10)*3-Math.max(0,order('notify')-1)*8);const recordScore=clamp(100-order('record')*14);const refundScore=clamp(100-order('refund')*10);const accountability=clamp((recordScore+refundScore)/2);const metrics={triage,investigation,containment,communication,accountability};const score=clamp(triage*.2+investigation*.2+containment*.3+communication*.15+accountability*.15);saveMetricResult('bug-bounty',metrics);saveResult('bug-bounty',score);stage.value='result'}
const liability=computed(()=>damage.value<=3500?'LOW':damage.value<=6000?'MEDIUM':'HIGH');
const coachText=computed(()=>({
brief:'Ready? I will stay right here.',
catch:'Read the clue, not just the name.',
trace:'Open every source before deciding.',
handoff:'Deep breath. The clock starts next.',
damage:completed.value.includes('stop')?'Nice containment! Finish the response.':'Hint: stop the harm before it grows.',
result:liability.value==='LOW'?'That was calm, clear, and kind.':'Every response teaches us something.'
}[stage.value]));
watch(stage,()=>nextTick(()=>window.scrollTo({top:0,behavior:'smooth'})));
onUnmounted(()=>{clearInterval(damageTimer);clearInterval(actionTimer)});
</script>
<template><main class="campaign-wrap"><aside v-if="stage!=='damage'&&stage!=='result'" class="game-coach" :class="`coach-${stage}`"><div class="coach-message"><span>ETHICSIM SAYS</span>{{coachText}}</div><MascotCharacter variant="coach" :show-speech="false" /></aside><nav class="campaign-progress"><span v-for="(name,i) in ['Bug Intake','Trace & Contain','Damage Control']" :key="name" :class="{active:(stage==='brief'||stage==='catch')?i===0:stage==='trace'?i===1:i===2,done:(stage==='trace'&&i===0)||(stage!=='brief'&&stage!=='catch'&&stage!=='trace'&&i<2)}"><b>0{{i+1}}</b>{{name}}</span></nav>
<section v-if="stage==='brief'" class="story-brief"><p class="label-mono">BUG CONTROL SHIFT · FRIDAY 16:42</p><h1>One small bug.<br><em>One expensive night.</em></h1><p>You are the incident officer at Northstar Bank. Triage incoming bugs, trace the one that escaped, then take control when it reaches production.</p><div class="mission-strip"><span>ROLE<strong>Incident Officer</strong></span><span>CAMPAIGN<strong>3 connected games</strong></span><span>OBJECTIVE<strong>Minimize user harm</strong></span></div><button class="btn-solid" @click="stage='catch'">Begin shift</button></section>
<section v-else-if="stage==='catch'" class="game-screen"><header><p class="label-mono">GAME 01 · BUG INTAKE</p><h1>Catch. Drag. Sort.</h1><p>{{bugs.length}} bugs are loose in the intake chamber. Hold and drag each one into the correct response basket.</p></header><div class="bug-chamber multi-bug cute-chamber" :class="`bug-count-${bugs.length}`"><div class="chamber-decor" aria-hidden="true"><i>✦</i><i>+</i><i>·</i><i>✦</i><i>+</i></div><div class="chamber-counter"><i></i>SORTED {{Object.keys(placements).length}} / {{bugs.length}}</div><button v-for="(bug,i) in bugs" v-show="!placements[i]" :key="bug.name" draggable="true" class="flying-bug" :class="[`flight-${i%4}`,`bug-tone-${i%4}`,{dragging:draggedBug===i,selected:draggedBug===i}]" @pointerdown="draggedBug=i" @click="draggedBug=i" @dragstart="startDrag(i,$event)" @dragend="draggedBug=null" :aria-label="`Drag ${bug.name}. ${bug.clue}`"><svg class="bug-avatar" viewBox="0 0 120 108" aria-hidden="true"><g class="bug-legs"><path d="M38 62 22 69M36 76 20 85M82 62 98 69M84 76 100 85"/></g><g class="bug-antennae"><path d="M48 29C43 17 35 14 29 10M72 29C77 17 85 14 91 10"/><circle cx="28" cy="9" r="4"/><circle cx="92" cy="9" r="4"/></g><g class="bug-wings"><path class="bug-wing-left" d="M48 45C32 35 14 43 13 61c-1 17 14 27 34 21Z"/><path class="bug-wing-right" d="M72 45c16-10 34-2 35 16 1 17-14 27-34 21Z"/></g><path class="bug-body" d="M34 58c0-24 11-37 26-37s26 13 26 37v18c0 16-11 26-26 26S34 92 34 76Z"/><path class="bug-belly" d="M43 76c5 5 29 5 34 0v8c0 10-7 16-17 16s-17-6-17-16Z"/><g class="bug-eyes"><ellipse cx="49" cy="52" rx="8" ry="10"/><ellipse cx="71" cy="52" rx="8" ry="10"/><circle cx="51" cy="50" r="3"/><circle cx="73" cy="50" r="3"/></g><circle class="bug-cheek" cx="43" cy="65" r="5"/><circle class="bug-cheek" cx="77" cy="65" r="5"/><path class="bug-smile" d="M54 64q6 7 12 0"/><text x="60" y="91" text-anchor="middle">{{bug.icon}}</text></svg><span class="bug-name">{{bug.name}}</span><small>{{bug.clue}}</small></button></div><div class="basket-row habitat-row"><div v-for="bin in bins" :key="bin.id" class="bug-basket habitat-box" :class="[`basket-${bin.id}`,{ready:draggedBug!==null}]" role="button" tabindex="0" @click="placeBug(bin.id,draggedBug)" @keydown.enter="placeBug(bin.id,draggedBug)" @dragover.prevent @drop.prevent="dropBug(bin.id,$event)"><div class="habitat-lid" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i></div><div class="basket-mouth"><b class="habitat-icon">{{bin.icon}}</b><span><strong>{{bin.label}}</strong><small>{{bin.hint}}</small></span><em>{{Object.values(placements).filter(value=>value===bin.id).length}}</em></div><div class="basket-items"><span v-for="(placed,index) in placements" v-show="placed===bin.id" :key="index">{{bugs[Number(index)]?.icon}} {{bugs[Number(index)]?.name}}</span><p v-if="!Object.values(placements).includes(bin.id)">waiting for a tiny guest...</p></div><div class="habitat-floor" aria-hidden="true"><i></i><i></i><i></i></div></div></div><div class="drag-help">TIP · Drag a moving bug into a basket. On touch screens, tap the bug and then tap its basket.</div><div v-if="catchFeedback" class="story-feedback"><p>{{catchFeedback}}</p><button v-if="Object.keys(placements).length===bugs.length" class="btn-solid" @click="continueToTrace">Follow the Receipt Beetle</button></div></section>
<section v-else-if="stage==='trace'" class="game-screen"><header><p class="label-mono">GAME 02 · TRACE &amp; CONTAIN</p><h1>The Receipt Beetle reached production.</h1><p>Users report duplicate bank charges. Inspect all three sources and identify the root cause.</p></header><div class="evidence-grid"><button v-for="e in evidence" :key="e.id" :class="{open:opened.includes(e.id)}" @click="openEvidence(e.id)"><span class="evidence-icon">{{e.id==='retry'?'↻':e.id==='code'?'</>':'!'}}</span><strong>{{e.title}}</strong><p>{{opened.includes(e.id)?e.body:'SEALED · CLICK TO INSPECT'}}</p></button></div><div v-if="opened.length===3" class="diagnosis-panel"><p class="label-mono">SELECT ROOT CAUSE</p><div><button :disabled="!!traceChoice" @click="diagnose('network')">The network is too slow</button><button :disabled="!!traceChoice" @click="diagnose('hide')">The UI displays it twice</button><button :disabled="!!traceChoice" @click="diagnose('idempotency')">Missing duplicate-request protection</button></div></div><div v-if="traceChoice" class="story-feedback"><p>{{traceChoice==='idempotency'?'ROOT CAUSE CONFIRMED — A retry creates a second charge because the handler accepts the same request twice.':'ROOT CAUSE MISSED — The logs show two real charges. The handler needs duplicate-request protection.'}}</p><button class="btn-solid" @click="stage='handoff'">Prepare incident response</button></div></section>
<section v-else-if="stage==='handoff'" class="incident-alert"><p class="label-mono">LIVE SYSTEM MESSAGE</p><div class="alarm-word">PRODUCTION<br>INCIDENT!</div><p>The duplicate-transaction bug is active. Every second of delay affects more customers.</p><button class="danger-button" @click="startDamage">Enter control room</button></section>
<section v-else-if="stage==='damage'" class="control-room"><header><div><p class="label-mono red">GAME 03 · DAMAGE CONTROL</p><h1>MINIMIZE THE DAMAGE</h1></div><div class="damage-timer-coach"><div class="timer-bubble"><span>INCIDENT TIMER</span><strong>{{elapsed}} SEC</strong><small>● LIVE RESPONSE</small></div><MascotCharacter variant="coach" :show-speech="false" /></div></header><div class="damage-board"><div><span>DAMAGE</span><strong>${{damage.toLocaleString()}}</strong><small :class="{rising:!completed.includes('stop')}">{{completed.includes('stop')?'TRANSACTIONS FROZEN':'↑ +$300 / SEC'}}</small></div><div><span>USERS AFFECTED</span><strong>{{users}}</strong><small>ACTIVE INCIDENT</small></div><div><span>LIABILITY</span><strong>{{liability}}</strong><small>ESTIMATED EXPOSURE</small></div></div><div class="room-floor"><div class="incident-beetle" :class="{caught:completed.includes('stop')}" aria-hidden="true"><i><b></b><em></em></i><span>{{completed.includes('stop')?'CONTAINED':'RECEIPT BEETLE · RUNNING'}}</span></div><div class="operator" :class="activeAction?`at-${activeAction}`:''">◆<small>YOU</small></div><button v-for="a in actions" :key="a.id" :class="[`station-${a.id}`,{done:completed.includes(a.id),working:activeAction===a.id}]" :disabled="!!activeAction||completed.includes(a.id)" @click="runAction(a.id)"><strong>{{completed.includes(a.id)?'✓ '+a.label:a.label}}</strong><span>{{activeAction===a.id?remaining+' SEC':a.detail}}</span><small>{{a.seconds}} SEC</small></button></div><div class="incident-console"><span class="label-mono">INCIDENT LOG</span><p v-for="line in incidentLog.slice(0,3)" :key="line">› {{line}}</p><p v-if="!incidentLog.length">› Choose your first action. Damage continues while you work.</p></div></section>
<section v-else class="incident-result" :class="`result-${liability.toLowerCase()}`"><div class="result-hero"><div class="result-copy"><p class="result-status"><i></i> INCIDENT CLOSED · FINAL REPORT</p><h1>{{liability==='LOW'?'Controlled under pressure.':liability==='MEDIUM'?'Contained, with consequences.':'The delay became the damage.'}}</h1><p class="result-deck">The bug started the incident. Your decisions determined how far the impact travelled.</p></div><div class="result-verdict"><span>FINAL LIABILITY</span><strong>{{liability}}</strong><small>CASE 03 · CLOSED</small><MascotCharacter variant="coach" :show-speech="false" /></div></div><div class="final-metrics"><span><i>01</i>Users affected<strong>{{users}}</strong><small>PEOPLE IMPACTED</small></span><span><i>02</i>Financial damage<strong>${{damage.toLocaleString()}}</strong><small>TOTAL EXPOSURE</small></span><span><i>03</i>Response time<strong>{{elapsed}} sec</strong><small>TO FULL RESPONSE</small></span><span><i>04</i>Liability<strong>{{liability}}</strong><small>FINAL ASSESSMENT</small></span></div><div class="lesson"><div><p class="label-mono">THE RESPONSE LESSON</p><h2>Liability grows after the bug is known.</h2></div><p>The defect caused the incident, but response choices determined its scale. Contain harm, preserve evidence, communicate, restore users, and record what must change.</p><div class="lesson-track"><span>CONTAIN</span><i></i><span>DOCUMENT</span><i></i><span>RESTORE</span><i></i><span>LEARN</span></div></div><div class="result-actions"><RouterLink to="/results" class="btn-solid">View responsibility profile</RouterLink><RouterLink to="/" class="btn-ghost">Return to briefing</RouterLink></div></section></main></template>
